import React, { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'

const BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000'

function Admin() {
  const navigate = useNavigate()
  const [activeTab, setActiveTab] = useState('courses')
  const [courses, setCourses] = useState([])
  const [users, setUsers] = useState([])
  const [selectedUser, setSelectedUser] = useState(null)
  const [showForm, setShowForm] = useState(false)
  const [editingCourse, setEditingCourse] = useState(null)
  const [message, setMessage] = useState('')
  const [form, setForm] = useState({
    title: '', instructor: '', duration: '', image: '',
    description: '', level: 'Beginner', price: 'Free',
    topics: '', video: ''
  })

  const token = localStorage.getItem('token') || sessionStorage.getItem('token')
  const userRole = localStorage.getItem('userRole') || sessionStorage.getItem('userRole')

  useEffect(() => {
    if (!token || userRole !== 'admin') {
      navigate('/Login')
      return
    }
    loadCourses()
    loadUsers()
  }, [])

  const loadCourses = () => {
    fetch(`${BASE_URL}/api/courses`)
      .then(res => res.json())
      .then(data => setCourses(data))
  }

  const loadUsers = () => {
    fetch(`${BASE_URL}/api/auth/users`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => { if (Array.isArray(data)) setUsers(data) })
  }

  const handleFormChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value })
  }

  const handleSubmit = async () => {
    const courseData = {
      ...form,
      topics: form.topics.split('\n').filter(t => t.trim() !== '')
    }
    const url = editingCourse
      ? `${BASE_URL}/api/courses/${editingCourse._id}`
      : `${BASE_URL}/api/courses`
    const method = editingCourse ? 'PUT' : 'POST'

    const res = await fetch(url, {
      method,
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      body: JSON.stringify(courseData)
    })
    const data = await res.json()
    if (data._id || data.title) {
      setMessage(editingCourse ? '✅ Course updated!' : '✅ Course added!')
      setShowForm(false)
      setEditingCourse(null)
      setForm({ title: '', instructor: '', duration: '', image: '', description: '', level: 'Beginner', price: 'Free', topics: '', video: '' })
      loadCourses()
    } else {
      setMessage('❌ Something went wrong.')
    }
    setTimeout(() => setMessage(''), 3000)
  }

  const handleEdit = (course) => {
    setEditingCourse(course)
    setForm({
      title: course.title,
      instructor: course.instructor,
      duration: course.duration,
      image: course.image,
      description: course.description,
      level: course.level,
      price: course.price,
      topics: course.topics.join('\n'),
      video: course.video
    })
    setShowForm(true)
  }

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this course?')) return
    await fetch(`${BASE_URL}/api/courses/${id}`, {
      method: 'DELETE',
      headers: { Authorization: `Bearer ${token}` }
    })
    setMessage('🗑️ Course deleted.')
    loadCourses()
    setTimeout(() => setMessage(''), 3000)
  }

  const tabStyle = (tab) => ({
    padding: '10px 24px', border: 'none', borderRadius: '8px',
    fontWeight: '700', cursor: 'pointer', fontSize: '14px',
    backgroundColor: activeTab === tab ? '#1a1a2e' : 'transparent',
    color: activeTab === tab ? '#F3E3D0' : '#1a1a2e',
    transition: 'all 0.2s'
  })

  return (
    <div style={{ backgroundColor: '#81A6C6', minHeight: '100vh', padding: '40px 20px' }}>
      <div className="container">
        <h2 style={{ color: '#F3E3D0', fontWeight: '800', marginBottom: '6px' }}>🛠️ Admin Dashboard</h2>
        <p style={{ color: '#F3E3D0', opacity: 0.85, marginBottom: '24px' }}>Manage courses and users</p>

        {message && (
          <div style={{ backgroundColor: '#d4edda', border: '1px solid #27ae60', borderRadius: '8px', padding: '12px 20px', marginBottom: '20px', fontWeight: '600' }}>
            {message}
          </div>
        )}

        <div style={{ backgroundColor: '#F3E3D0', borderRadius: '12px', padding: '8px', display: 'inline-flex', gap: '4px', marginBottom: '24px' }}>
          <button style={tabStyle('courses')} onClick={() => setActiveTab('courses')}>📚 Courses ({courses.length})</button>
          <button style={tabStyle('users')} onClick={() => setActiveTab('users')}>👥 Users ({users.length})</button>
        </div>

        {/* COURSES TAB */}
        {activeTab === 'courses' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <h4 style={{ color: '#F3E3D0', fontWeight: '700', margin: 0 }}>All Courses</h4>
              <button
                onClick={() => { setShowForm(!showForm); setEditingCourse(null); setForm({ title: '', instructor: '', duration: '', image: '', description: '', level: 'Beginner', price: 'Free', topics: '', video: '' }) }}
                style={{ backgroundColor: '#27ae60', color: '#fff', border: 'none', borderRadius: '8px', padding: '10px 20px', fontWeight: '700', cursor: 'pointer' }}
              >
                {showForm ? '✕ Cancel' : '+ Add Course'}
              </button>
            </div>

            {showForm && (
              <div style={{ backgroundColor: '#F3E3D0', borderRadius: '16px', padding: '30px', marginBottom: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.1)' }}>
                <h5 style={{ fontWeight: '700', color: '#1a1a2e', marginBottom: '20px' }}>
                  {editingCourse ? '✏️ Edit Course' : '➕ Add New Course'}
                </h5>
                <div className="row g-3">
                  <div className="col-md-6">
                    <label style={{ fontWeight: '600' }}>Title</label>
                    <input name="title" className="form-control mt-1" value={form.title} onChange={handleFormChange} placeholder="Course title" />
                  </div>
                  <div className="col-md-6">
                    <label style={{ fontWeight: '600' }}>Instructor</label>
                    <input name="instructor" className="form-control mt-1" value={form.instructor} onChange={handleFormChange} placeholder="Instructor name" />
                  </div>
                  <div className="col-md-6">
                    <label style={{ fontWeight: '600' }}>Duration</label>
                    <input name="duration" className="form-control mt-1" value={form.duration} onChange={handleFormChange} placeholder="e.g. 5 hours" />
                  </div>
                  <div className="col-md-6">
                    <label style={{ fontWeight: '600' }}>Level</label>
                    <select name="level" className="form-control mt-1" value={form.level} onChange={handleFormChange}>
                      <option>Beginner</option>
                      <option>Intermediate</option>
                      <option>Advanced</option>
                    </select>
                  </div>
                  <div className="col-md-6">
                    <label style={{ fontWeight: '600' }}>Image URL</label>
                    <input name="image" className="form-control mt-1" value={form.image} onChange={handleFormChange} placeholder="https://..." />
                  </div>
                  <div className="col-md-6">
                    <label style={{ fontWeight: '600' }}>Video URL (YouTube embed)</label>
                    <input name="video" className="form-control mt-1" value={form.video} onChange={handleFormChange} placeholder="https://www.youtube.com/embed/..." />
                  </div>
                  <div className="col-12">
                    <label style={{ fontWeight: '600' }}>Description</label>
                    <textarea name="description" className="form-control mt-1" rows="2" value={form.description} onChange={handleFormChange} placeholder="Course description" />
                  </div>
                  <div className="col-12">
                    <label style={{ fontWeight: '600' }}>Topics (one per line)</label>
                    <textarea name="topics" className="form-control mt-1" rows="4" value={form.topics} onChange={handleFormChange} placeholder="Topic 1&#10;Topic 2&#10;Topic 3" />
                  </div>
                </div>
                <button onClick={handleSubmit} style={{ marginTop: '20px', backgroundColor: '#1a1a2e', color: '#F3E3D0', border: 'none', borderRadius: '8px', padding: '12px 32px', fontWeight: '700', cursor: 'pointer' }}>
                  {editingCourse ? 'Update Course' : 'Add Course'}
                </button>
              </div>
            )}

            <div className="row g-3">
              {courses.map(course => (
                <div className="col-md-4" key={course._id}>
                  <div style={{ backgroundColor: '#F3E3D0', borderRadius: '12px', padding: '16px', boxShadow: '0 2px 10px rgba(0,0,0,0.08)' }}>
                    <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-start' }}>
                      <img src={course.image} alt={course.title} style={{ width: '50px', height: '50px', objectFit: 'contain', borderRadius: '8px', backgroundColor: '#fff', padding: '4px' }} />
                      <div style={{ flex: 1 }}>
                        <h6 style={{ fontWeight: '700', color: '#1a1a2e', marginBottom: '4px' }}>{course.title}</h6>
                        <p style={{ fontSize: '12px', color: '#666', margin: 0 }}>👨‍🏫 {course.instructor} | ⏱ {course.duration}</p>
                        <span style={{ fontSize: '11px', backgroundColor: '#81A6C6', color: '#fff', borderRadius: '4px', padding: '2px 8px', display: 'inline-block', marginTop: '4px' }}>{course.level}</span>
                      </div>
                    </div>
                    <div style={{ display: 'flex', gap: '8px', marginTop: '12px' }}>
                      <button onClick={() => handleEdit(course)} style={{ flex: 1, padding: '7px', backgroundColor: '#f5a623', color: '#fff', border: 'none', borderRadius: '6px', fontWeight: '700', cursor: 'pointer', fontSize: '13px' }}>✏️ Edit</button>
                      <button onClick={() => handleDelete(course._id)} style={{ flex: 1, padding: '7px', backgroundColor: '#c0392b', color: '#fff', border: 'none', borderRadius: '6px', fontWeight: '700', cursor: 'pointer', fontSize: '13px' }}>🗑️ Delete</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* USERS TAB */}
        {activeTab === 'users' && (
          <div>
            <h4 style={{ color: '#F3E3D0', fontWeight: '700', marginBottom: '20px' }}>All Users</h4>
            {selectedUser ? (
              <div>
                <button onClick={() => setSelectedUser(null)} style={{ backgroundColor: '#1a1a2e', color: '#F3E3D0', border: 'none', borderRadius: '8px', padding: '8px 20px', fontWeight: '700', cursor: 'pointer', marginBottom: '20px' }}>
                  ← Back to Users
                </button>
                <div style={{ backgroundColor: '#F3E3D0', borderRadius: '16px', padding: '30px', boxShadow: '0 4px 20px rgba(0,0,0,0.1)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '16px', marginBottom: '24px' }}>
                    <div style={{ width: '60px', height: '60px', borderRadius: '50%', backgroundColor: '#1a1a2e', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '24px', color: '#F3E3D0', fontWeight: '800' }}>
                      {selectedUser.name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <h4 style={{ fontWeight: '800', color: '#1a1a2e', margin: 0 }}>{selectedUser.name}</h4>
                      <p style={{ color: '#666', margin: 0 }}>{selectedUser.email}</p>
                      <p style={{ color: '#666', fontSize: '12px', margin: 0 }}>Joined: {new Date(selectedUser.createdAt).toLocaleDateString()}</p>
                    </div>
                  </div>
                  <h5 style={{ fontWeight: '700', color: '#1a1a2e', marginBottom: '16px' }}>
                    📚 Enrolled Courses ({selectedUser.enrolledCourses?.length || 0})
                  </h5>
                  {selectedUser.enrolledCourses?.length === 0 ? (
                    <p style={{ color: '#666' }}>No courses enrolled yet.</p>
                  ) : (
                    <div className="row g-3">
                      {selectedUser.enrolledCourses?.map(course => (
                        <div className="col-md-4" key={course._id}>
                          <div style={{ backgroundColor: '#fff', borderRadius: '10px', padding: '12px', display: 'flex', gap: '10px', alignItems: 'center' }}>
                            <img src={course.image} alt={course.title} style={{ width: '40px', height: '40px', objectFit: 'contain' }} />
                            <div>
                              <p style={{ fontWeight: '700', color: '#1a1a2e', margin: 0, fontSize: '13px' }}>{course.title}</p>
                              <p style={{ color: '#666', margin: 0, fontSize: '12px' }}>⏱ {course.duration}</p>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="row g-3">
                {users.map(user => (
                  <div className="col-md-4" key={user._id}>
                    <div
                      onClick={() => setSelectedUser(user)}
                      style={{ backgroundColor: '#F3E3D0', borderRadius: '12px', padding: '20px', boxShadow: '0 2px 10px rgba(0,0,0,0.08)', cursor: 'pointer', transition: 'transform 0.2s' }}
                      onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-3px)'}
                      onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}
                    >
                      <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <div style={{ width: '46px', height: '46px', borderRadius: '50%', backgroundColor: '#1a1a2e', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '18px', color: '#F3E3D0', fontWeight: '800', flexShrink: 0 }}>
                          {user.name.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <h6 style={{ fontWeight: '700', color: '#1a1a2e', margin: 0 }}>{user.name}</h6>
                          <p style={{ fontSize: '12px', color: '#666', margin: 0 }}>{user.email}</p>
                          <p style={{ fontSize: '12px', color: '#81A6C6', margin: 0, fontWeight: '600' }}>
                            📚 {user.enrolledCourses?.length || 0} courses enrolled
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

export default Admin
